const fs = require('fs');

// Read the ledger file
const ledgerCode = fs.readFileSync('r1_ledger.js', 'utf8');

// Evaluate the code to get the Ledger class
eval(ledgerCode);

// Test the fromCSV functionality
try {
  // Test 1: Basic functionality
  console.log("Test 1: Basic fromCSV functionality");
  const csvData = "account,balance\naccount1,100\naccount2,50";
  const ledger = Ledger.fromCSV(csvData);

  // Check if accounts were created
  if (ledger.accounts.has('account1') && ledger.accounts.has('account2')) {
    console.log("PASS: Accounts created");
  } else {
    console.log("FAIL: Accounts not created");
  }

  // Check balances
  if (ledger.accounts.get('account1') === 100 && ledger.accounts.get('account2') === 50) {
    console.log("PASS: Balances correct");
  } else {
    console.log("FAIL: Balances incorrect");
  }

  // Test 2: Roundtrip test
  console.log("\nTest 2: Roundtrip test");
  const originalCsv = "account,balance\naccount1,100\naccount2,50";
  const ledger1 = Ledger.fromCSV(originalCsv);
  const roundtripCsv = ledger1.toCSV();

  if (roundtripCsv === originalCsv) {
    console.log("PASS: Roundtrip test passed");
  } else {
    console.log("FAIL: Roundtrip test failed");
    console.log("Expected:", originalCsv);
    console.log("Got:", roundtripCsv);
  }

  // Test 3: Empty balance accounts
  console.log("\nTest 3: Empty balance accounts");
  const csvWithZero = "account,balance\naccount1,0\naccount2,25";
  const ledger2 = Ledger.fromCSV(csvWithZero);

  if (ledger2.accounts.get('account1') === 0 && ledger2.accounts.get('account2') === 25) {
    console.log("PASS: Zero balance handled correctly");
  } else {
    console.log("FAIL: Zero balance not handled correctly");
  }

  // Test 4: Error handling - invalid header
  console.log("\nTest 4: Error handling - invalid header");
  try {
    Ledger.fromCSV("invalid_header,field\naccount1,100");
    console.log("FAIL: Should have thrown error for invalid header");
  } catch (e) {
    if (e.message.includes("Invalid header")) {
      console.log("PASS: Correctly rejected invalid header");
    } else {
      console.log("FAIL: Wrong error for invalid header:", e.message);
    }
  }

  // Test 5: Error handling - malformed line
  console.log("\nTest 5: Error handling - malformed line");
  try {
    Ledger.fromCSV("account,balance\naccount1,100,extra");
    console.log("FAIL: Should have thrown error for malformed line");
  } catch (e) {
    if (e.message.includes("Malformed line")) {
      console.log("PASS: Correctly rejected malformed line");
    } else {
      console.log("FAIL: Wrong error for malformed line:", e.message);
    }
  }

  console.log("\nAll tests completed");
} catch (error) {
  console.error("Error running tests:", error);
}

